import React, { createContext, useContext, useReducer, useEffect } from 'react';
import { useLocalStorage } from '../hooks/useLocalStorage';
import { useOffline } from './OfflineContext';
import indexedDBService from '../services/indexedDBService';
import apiService from '../services/apiService';

const DonorContext = createContext();

const initialState = {
    donors: [],
    agentAssignments: [],
    loading: false,
    error: null
};

function donorReducer(state, action) {
    switch (action.type) {
        case 'ADD_DONOR':
            return {
                ...state,
                donors: [...state.donors, action.payload]
            };
        case 'SET_DONORS':
            return {
                ...state,
                donors: action.payload
            };
        case 'UPDATE_DONOR':
            return {
                ...state,
                donors: state.donors.map(donor =>
                    donor.id === action.payload.id ? action.payload : donor
                )
            };
        case 'DELETE_DONOR':
            return {
                ...state,
                donors: state.donors.filter(donor => donor.id !== action.payload)
            };
        case 'SET_AGENT_ASSIGNMENTS':
            return {
                ...state,
                agentAssignments: action.payload
            };
        case 'SET_LOADING':
            return {
                ...state,
                loading: action.payload
            };
        case 'SET_ERROR':
            return {
                ...state,
                error: action.payload
            };
        default:
            return state;
    }
}

export const DonorProvider = ({ children }) => {
    const [storedDonors, setStoredDonors] = useLocalStorage('donors', []);
    const [storedAssignments, setStoredAssignments] = useLocalStorage('agentAssignments', []);
    const { isOffline, api } = useOffline();

    const [state, dispatch] = useReducer(donorReducer, {
        ...initialState,
        donors: storedDonors,
        agentAssignments: storedAssignments
    });

    // Sync state with localStorage whenever donors or assignments change
    useEffect(() => {
        setStoredDonors(state.donors);
    }, [state.donors, setStoredDonors]);

    useEffect(() => {
        setStoredAssignments(state.agentAssignments);
    }, [state.agentAssignments, setStoredAssignments]);

    // Initialize data from IndexedDB
    useEffect(() => {
        const fetchData = async () => {
            try {
                const donors = await indexedDBService.donors.getAll();
                if (donors && donors.length > 0) {
                    dispatch({ type: 'SET_DONORS', payload: donors });
                }

                // We don't have a dedicated method for agent assignments in IndexedDB
                // This would need to be implemented or handled differently
            } catch (error) {
                console.error('Error loading data from IndexedDB:', error);
            }
        };
        fetchData();
    }, []);

    // Add a new donor
    const addDonor = async (donor) => {
        const newDonor = {
            ...donor,
            id: Date.now().toString(),
            createdAt: new Date().toISOString(),
            status: 'pending'
        };

        dispatch({ type: 'ADD_DONOR', payload: newDonor });

        try {
            if (!isOffline) {
                const serverDonor = await apiService.createDonor({
                    first_name: newDonor.firstName,
                    last_name: newDonor.lastName,
                    whatsapp_number: newDonor.whatsappNumber
                });

                // Update local donor with server ID if needed
                if (serverDonor && serverDonor.id) {
                    const updatedDonor = { ...newDonor, serverId: serverDonor.id };
                    dispatch({ type: 'UPDATE_DONOR', payload: updatedDonor });
                }
            } else {
                // Use the offline-aware API wrapper
                await api.createDonor({
                    first_name: newDonor.firstName,
                    last_name: newDonor.lastName,
                    whatsapp_number: newDonor.whatsappNumber
                });
            }
        } catch (error) {
            console.error('Error creating donor:', error);
        }

        return newDonor;
    };

    // Update donor status and information
    const updateDonor = async (donor) => {
        dispatch({ type: 'UPDATE_DONOR', payload: donor });

        try {
            if (!isOffline) {
                await apiService.updateDonor(donor.serverId || donor.id, {
                    first_name: donor.firstName,
                    last_name: donor.lastName,
                    whatsapp_number: donor.whatsappNumber
                });
            } else {
                await api.updateDonor(donor.serverId || donor.id, {
                    first_name: donor.firstName,
                    last_name: donor.lastName,
                    whatsapp_number: donor.whatsappNumber
                });
            }
        } catch (error) {
            console.error('Error updating donor:', error);
        }
    };

    // Delete a donor
    const deleteDonor = async (id) => {
        const donor = state.donors.find(d => d.id === id);
        if (!donor) return;

        dispatch({ type: 'DELETE_DONOR', payload: id });

        try {
            if (!isOffline) {
                await apiService.deleteDonor(donor.serverId || id);
            } else {
                // Queue for deletion when back online
                await indexedDBService.donors.delete(id, true);
            }
        } catch (error) {
            console.error('Error deleting donor:', error);
        }
    };

    // Split donors among agents
    const splitDonors = async (agentCount) => {
        if (!agentCount || agentCount < 1) return;

        const pendingDonors = state.donors.filter(donor =>
            donor.status === 'pending' && donor.type === 'sheep'
        );

        // Group cow donors separately (they need 7 people per cow)
        const cowDonors = state.donors.filter(donor => donor.type === 'cow');
        const cowGroups = [];

        for (let i = 0; i < Math.floor(cowDonors.length / 7); i++) {
            cowGroups.push(cowDonors.slice(i * 7, (i + 1) * 7));
        }

        // Calculate how many donors each agent gets
        const donorsPerAgent = Math.ceil(pendingDonors.length / agentCount);

        // Create agent assignments
        const assignments = [];

        for (let i = 0; i < agentCount; i++) {
            const start = i * donorsPerAgent;
            const end = Math.min(start + donorsPerAgent, pendingDonors.length);

            assignments.push({
                id: `agent-${i + 1}`,
                name: `Agent ${i + 1}`,
                donors: pendingDonors.slice(start, end).map(d => d.id),
                cowGroups: i < cowGroups.length ? [cowGroups[i].map(d => d.id)] : []
            });
        }

        // Distribute remaining cow groups
        for (let i = agentCount; i < cowGroups.length; i++) {
            const agentIndex = i % agentCount;
            assignments[agentIndex].cowGroups.push(
                cowGroups[i].map(d => d.id)
            );
        }

        dispatch({ type: 'SET_AGENT_ASSIGNMENTS', payload: assignments });

        try {
            if (!isOffline) {
                // Update the agent assignments on the server
                // This would need a proper API endpoint
                const agentNames = assignments.map(a => a.name);
                await apiService.splitDonations(agentNames);
            } else {
                // Store locally for later sync
                // We should add this to the sync queue
                await addToSyncQueue(assignments);
            }
        } catch (error) {
            console.error('Error splitting donors:', error);
        }

        return assignments;
    };

    // Helper function to add to sync queue
    const addToSyncQueue = async (data) => {
        try {
            await indexedDBService.addToSyncQueue('split', 'agents', data);
        } catch (error) {
            console.error('Error adding to sync queue:', error);
        }
    };

    // Mark donor as done with uploaded media
    const markDonorAsDone = async (id, media) => {
        const donor = state.donors.find(d => d.id === id);
        if (!donor) return;

        const updatedDonor = {
            ...donor,
            status: 'sending', // Will be updated to 'done' after sync
            media,
            completedAt: new Date().toISOString()
        };

        await updateDonor(updatedDonor);

        try {
            if (!isOffline) {
                // Upload media to the server
                if (media.images) {
                    for (const image of media.images) {
                        await apiService.uploadMedia(donor.serverId || donor.id, 'image', image);
                    }
                }
                if (media.video) {
                    await apiService.uploadMedia(donor.serverId || donor.id, 'video', media.video);
                }

                // Update status to done
                await apiService.updateDonationStatus(donor.serverId || donor.id, 'done');

                // Update local status
                updatedDonor.status = 'done';
                dispatch({ type: 'UPDATE_DONOR', payload: updatedDonor });
            } else {
                // Queue media uploads for when back online
                if (media.images) {
                    for (const image of media.images) {
                        await api.uploadMedia(donor.id, 'image', image);
                    }
                }
                if (media.video) {
                    await api.uploadMedia(donor.id, 'video', media.video);
                }
            }
        } catch (error) {
            console.error('Error processing media:', error);
        }

        return updatedDonor;
    };

    // Get donors for a specific agent
    const getDonorsByAgent = (agentId) => {
        const assignment = state.agentAssignments.find(a => a.id === agentId);
        if (!assignment) return [];

        const sheepDonors = assignment.donors.map(id =>
            state.donors.find(d => d.id === id)
        ).filter(Boolean);

        const cowDonors = assignment.cowGroups.flatMap(group =>
            group.map(id => state.donors.find(d => d.id === id))
        ).filter(Boolean);

        return { sheepDonors, cowDonors };
    };

    return (
        <DonorContext.Provider value={{
            donors: state.donors,
            loading: state.loading,
            error: state.error,
            agentAssignments: state.agentAssignments,
            addDonor,
            updateDonor,
            deleteDonor,
            splitDonors,
            markDonorAsDone,
            getDonorsByAgent
        }}>
            {children}
        </DonorContext.Provider>
    );
};

export const useDonors = () => useContext(DonorContext);
